// AI Agent ka output lo
let raw = $input.first().json.output;

let data;

if (typeof raw === 'string') {
  // model kabhi kabhi ```json laga deta hai
  raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  try {
    data = JSON.parse(raw);
  } catch (e) {
    throw new Error('Model ne sahi JSON nahi bheja. Mila: ' + raw.slice(0, 200));
  }
} else {
  data = raw;          // pehle se object hai, parse mat karo
}

return [{
  json: {
    city: data.city ?? null,
    temperature: data.temperature ?? null,
    condition: data.condition ?? null,
    message: data.message ?? '',
    output: data.message ?? ''      // chat window ke liye
  }
}];
